const response = $json;
const statusCode = Number(response.statusCode || 0);
const body = response.body && typeof response.body === 'object' ? response.body : response;
let state = 'UNKNOWN';
let reason = 'health source returned no canonical state';
if ((statusCode && statusCode !== 200) || response.error || response.errorMessage) {
  state = 'SOURCE_UNAVAILABLE';
  reason = statusCode ? `health source returned HTTP ${statusCode}` : 'health source could not be reached';
} else if (body.status === true || body.state === 'UP' || response.status === true) {
  state = 'UP';
  reason = 'canonical HADES health status';
} else if (body.status === false || body.state === 'DOWN' || response.status === false) {
  state = 'DOWN';
  reason = 'canonical HADES health status';
}
const memory = $getWorkflowStaticData('global');
const previous = memory.last_hades_state || '';
const transition = previous && previous !== state ? `${previous}->${state}` : '';
const notify = transition && ['UP', 'DOWN', 'SOURCE_UNAVAILABLE'].includes(state);
memory.last_hades_state = state;
return [{ json: { automation_id: 'epsilon-server-health-watch-core', resource_id: 'hades-core', hades_state: state, hades_reason: reason, hades_transition: transition, hades_notification: notify ? `HADES Server Health Watch — Core: ${state}` : '' } }];
